function stable(value,seen=new Set()) {
 if(value===undefined)return {type:'undefined'};
 if(typeof value==='number'&&!Number.isFinite(value))return {type:String(value)};
 if(typeof value==='function')return {type:'function'};
 if(value===null||typeof value!=='object')return value;
 if(seen.has(value))return {type:'cycle'};
 seen.add(value);
 let result;
 if(Array.isArray(value))result=value.map(v=>stable(v,seen));
 else {result={};for(const key of Object.keys(value).sort())result[key]=stable(value[key],seen);}
 seen.delete(value);return result;
}
function nativeError(error){return {name:String(error&&error.name||'Error'),message:String(error&&error.message||error)};}

